package com.carparts.platform.workflow;

import com.carparts.platform.auth.AuthPrincipal;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;

@Service
public class CommerceService {
    private final JdbcTemplate jdbc; private final WorkflowService workflow;
    public CommerceService(JdbcTemplate jdbc,WorkflowService workflow){this.jdbc=jdbc;this.workflow=workflow;}
    public record OrderInput(String currency,BigDecimal totalAmount,String customerNote,String internalNote){}
    public record PaymentInput(BigDecimal amount,String currency,String method,String reference,String status){}
    public record ShipmentInput(UUID orderId,String trackingNumber,String carrier,String originCountry,String destinationCountry,LocalDate eta){}
    public record ShipmentStatus(String status,String customsStatus){}
    @Transactional public Map<String,Object> createOrder(UUID caseId,OrderInput in,AuthPrincipal actor){if(in.currency()==null||in.totalAmount()==null||in.totalAmount().signum()<0)throw bad("ارز و مبلغ سفارش الزامی است.");Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM sales_orders WHERE case_id=?",Integer.class,caseId);if(exists!=null&&exists>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"برای این پرونده قبلاً سفارش ساخته شده است.");UUID customer=jdbc.query("SELECT r.customer_id FROM workflow_cases c JOIN customer_requests r ON r.id=c.request_id WHERE c.id=?",rs->rs.next()?rs.getObject("customer_id",UUID.class):null,caseId);UUID id=jdbc.queryForObject("INSERT INTO sales_orders(case_id,customer_id,currency,total_amount,status,customer_note,internal_note) VALUES (?,?,?,?, 'CONFIRMED',?,?) RETURNING id",UUID.class,caseId,customer,in.currency().toUpperCase(),in.totalAmount(),in.customerNote(),in.internalNote());event(caseId,"ORDER_CREATED","سفارش فروش ایجاد شد",actor.id());return jdbc.queryForMap("SELECT * FROM sales_orders WHERE id=?",id);}
    @Transactional public Map<String,Object> addPayment(UUID orderId,PaymentInput in,AuthPrincipal actor){if(in.amount()==null||in.amount().signum()<=0||in.currency()==null)throw bad("مبلغ و ارز پرداخت الزامی است.");String status=in.status()==null?"PENDING":in.status();if(!Set.of("PENDING","CONFIRMED","FAILED","REFUNDED").contains(status))throw bad("وضعیت پرداخت نامعتبر است.");UUID id=jdbc.queryForObject("INSERT INTO payments(order_id,amount,currency,method,reference,status,received_at,created_by_user_id) VALUES (?,?,?,?,?,?,CASE WHEN ?='CONFIRMED' THEN NOW() ELSE NULL END,?) RETURNING id",UUID.class,orderId,in.amount(),in.currency().toUpperCase(),in.method(),in.reference(),status,status,actor.id());if("CONFIRMED".equals(status))jdbc.update("UPDATE sales_orders SET paid_amount=paid_amount+?,updated_at=NOW() WHERE id=?",in.amount(),orderId);return jdbc.queryForMap("SELECT * FROM payments WHERE id=?",id);}
    @Transactional public Map<String,Object> addShipment(UUID caseId,ShipmentInput in,AuthPrincipal actor){UUID id=jdbc.queryForObject("INSERT INTO shipments(case_id,order_id,tracking_number,carrier,origin_country,destination_country,status,eta) VALUES (?,?,?,?,?,?,'PREPARING',?) RETURNING id",UUID.class,caseId,in.orderId(),in.trackingNumber(),in.carrier(),in.originCountry(),in.destinationCountry(),in.eta());if(in.orderId()!=null)jdbc.update("UPDATE sales_orders SET status='PROCUREMENT',updated_at=NOW() WHERE id=?",in.orderId());event(caseId,"SHIPMENT_CREATED","پرونده حمل ایجاد شد",actor.id());return jdbc.queryForMap("SELECT * FROM shipments WHERE id=?",id);}
    @Transactional public Map<String,Object> shipmentStatus(UUID shipmentId,ShipmentStatus in,AuthPrincipal actor){if(!Set.of("PREPARING","PICKED_UP","IN_TRANSIT","ARRIVED_COUNTRY","CUSTOMS","RELEASED","LOCAL_DELIVERY","DELIVERED").contains(in.status()))throw bad("وضعیت حمل نامعتبر است.");Map<String,Object> old=jdbc.queryForMap("SELECT case_id,order_id FROM shipments WHERE id=?",shipmentId);jdbc.update("UPDATE shipments SET status=?,customs_status=?,departed_at=CASE WHEN ? IN ('PICKED_UP','IN_TRANSIT') THEN COALESCE(departed_at,NOW()) ELSE departed_at END,arrived_at=CASE WHEN ?='DELIVERED' THEN NOW() ELSE arrived_at END,updated_at=NOW() WHERE id=?",in.status(),in.customsStatus(),in.status(),in.status(),shipmentId);UUID caseId=(UUID)old.get("case_id"),orderId=(UUID)old.get("order_id");if(caseId!=null){if("IN_TRANSIT".equals(in.status()))workflow.transition(caseId,new WorkflowService.Transition("IN_TRANSIT","وضعیت حمل به در حال ارسال تغییر کرد",null,null),actor);else if("CUSTOMS".equals(in.status()))workflow.transition(caseId,new WorkflowService.Transition("CUSTOMS","مرسوله وارد گمرک شد",null,null),actor);else if("DELIVERED".equals(in.status()))workflow.transition(caseId,new WorkflowService.Transition("DELIVERED","مرسوله تحویل شد",null,null),actor);}if(orderId!=null){String os=switch(in.status()){case "IN_TRANSIT","PICKED_UP"->"IN_TRANSIT";case "CUSTOMS","ARRIVED_COUNTRY"->"CUSTOMS";case "LOCAL_DELIVERY","RELEASED"->"READY";case "DELIVERED"->"DELIVERED";default->"PROCUREMENT";};jdbc.update("UPDATE sales_orders SET status=?,updated_at=NOW() WHERE id=?",os,orderId);}return jdbc.queryForMap("SELECT * FROM shipments WHERE id=?",shipmentId);}
    public Map<String,Object> commerce(UUID caseId){Map<String,Object> out=new LinkedHashMap<>();List<Map<String,Object>> orders=jdbc.queryForList("SELECT * FROM sales_orders WHERE case_id=?",caseId);out.put("orders",orders);out.put("payments",orders.isEmpty()?List.of():jdbc.queryForList("SELECT * FROM payments WHERE order_id=? ORDER BY created_at DESC",orders.getFirst().get("id")));out.put("shipments",jdbc.queryForList("SELECT * FROM shipments WHERE case_id=? ORDER BY created_at DESC",caseId));return out;}
    private void event(UUID caseId,String type,String note,UUID actor){jdbc.update("INSERT INTO workflow_events(case_id,event_type,note,created_by_user_id) VALUES (?,?,?,?)",caseId,type,note,actor);}
    private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);}
}
